from collections import deque


class Solution:
    def foreignDictionary(self, words: List[str]) -> str:
        adj = {c: set() for w in words for c in w}
        for a, b in zip(words, words[1:]):
            for x, y in zip(a, b):
                if x != y:
                    adj[x].add(y)
                    break
            else:
                if len(a) > len(b):
                    return ""
        indeg = {c: 0 for c in adj}
        for u in adj:
            for v in adj[u]:
                indeg[v] += 1
        queue = deque(c for c in adj if indeg[c] == 0)
        order = []
        while queue:
            u = queue.popleft()
            order.append(u)
            for v in adj[u]:
                indeg[v] -= 1
                if indeg[v] == 0:
                    queue.append(v)
        return "".join(order) if len(order) == len(adj) else ""
